def is_simple_power(x, n):
    """Returns True if x is a simple power of n, False otherwise."""
    if x == 0:
        return n == 0
    if n == 0:
        return False
    if x == 1:
        return True
    if n == 1:
        return False

    abs_x = abs(x)
    abs_n = abs(n)

    if abs_n == 1:
        return abs_x == 1

    k = 0
    current = abs_x
    while current != 1:
        if current % abs_n != 0:
            return False
        current = current // abs_n
        k += 1

    if n > 0:
        return x > 0
    else:
        return (k % 2 == 1 and x < 0) or (k % 2 == 0 and x > 0)

