def iscube(a):
    '''
    Write a function that takes an integer a and returns True 
    if this integer is a cube of some integer number.
    '''
    if a == 0:
        return True
    sign = 1 if a > 0 else -1
    abs_a = abs(a)
    low, high = 0, abs_a
    while low <= high:
        mid = (low + high) // 2
        cube = mid ** 3
        if cube == abs_a:
            return True
        elif cube < abs_a:
            low = mid + 1
        else:
            high = mid - 1
    return False

