def decimal_to_binary(decimal):
    """Converts a decimal number to a binary string with 'db' prefix and suffix."""
    # Handle float inputs that are integers
    if isinstance(decimal, float):
        if not decimal.is_integer():
            raise ValueError("Input must be an integer")
        decimal = int(decimal)
    # Check if input is an integer
    elif not isinstance(decimal, int):
        raise ValueError("Input must be an integer")
    # Check if non-negative
    if decimal < 0:
        raise ValueError("Input must be non-negative")
    # Convert to binary and format
    binary = bin(decimal)[2:]
    return f"db{binary}db"

cleaned_prediction:
def decimal_to_binary(decimal):
    """Converts a decimal number to a binary string with 'db' prefix and suffix."""
    # Handle float inputs that are integers
    if isinstance(decimal, float):
        if not decimal.is_integer():
            raise ValueError("Input must be an integer")
        decimal = int(decimal)
    # Check if input is an integer
    elif not isinstance(decimal, int):
        raise ValueError("Input must be an integer")
    # Check if non-negative
    if decimal < 0:
        raise ValueError("Input must be non-negative")
    # Convert to binary and format
    binary = bin(decimal)[2:]
    return f"db{binary}db"

