def is_happy(s):
    """Check if a string is 'happy' based on given criteria."""
    if not isinstance(s, str):
        return False
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        # Check if all three consecutive characters are unique
        if len({s[i], s[i+1], s[i+2]}) != 3:
            return False
    return True

