    if gpa == 4.0:
        letter_grade.append("A+")
    elif gpa > 3.7:
        letter_grade.append("A")
    elif gpa > 3.3:
        letter_grade.append("A-")
    elif gpa > 3.0:
        letter_grade.append("B+")
    elif gpa > 2.7:
        letter_grade.append("B")
    elif gpa > 2.3:
        letter_grade.append("B-")
    elif gpa > 2.0:
        letter_grade.append("C+")
    elif gpa > 1.7:
        letter_grade.append("C")
