import heapq

def minPath(grid, k):
    N = len(grid)
    heap = []
    # Initialize the heap with all possible starting cells
    for i in range(N):
        for j in range(N):
            initial_path = [grid[i][j]]
            heapq.heappush(heap, (initial_path, i, j))

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while heap:
        current_path, i, j = heapq.heappop(heap)
        if len(current_path) == k:
            return current_path
        # Explore all four possible directions
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < N and 0 <= nj < N:
                new_path = current_path + [grid[ni][nj]]
                heapq.heappush(heap, (new_path, ni, nj))

    # The problem guarantees a unique answer, so this return is a fallback
    return []

